import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import math
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

cpp_source = """
torch::Tensor moe_gated_gemm_forward(
    torch::Tensor x,
    torch::Tensor gate_proj,
    torch::Tensor up_proj,
    torch::Tensor down_proj,
    torch::Tensor expert_indices,
    torch::Tensor expert_weights);
"""

hip_source = """
#include <hip/hip_runtime.h>
#include <c10/cuda/CUDAGuard.h>

#define CEILDIV(a, b) ((a + b - 1) / b)

#define SILU(x) ((x) / (1.0f + expf(-(x))))

__global__ void moe_gated_gemm_kernel(
    const float* __restrict__ x,
    const float* __restrict__ gate_proj,
    const float* __restrict__ up_proj,
    const float* __restrict__ down_proj,
    const int* __restrict__ expert_indices,
    const float* __restrict__ expert_weights,
    float* __restrict__ output,
    const int num_tokens,
    const int num_experts,
    const int hidden_size,
    const int intermediate_size,
    const int top_k
) {

    const int tid = blockIdx.x * blockDim.x + threadIdx.x;

    if (tid >= num_tokens * top_k * hidden_size) {
        return;
    }

    const int token_idx = (tid / hidden_size) / top_k;
    const int expert_slot = (tid / hidden_size) % top_k;
    const int hidden_dim = tid % hidden_size;

    if (token_idx >= num_tokens) {
        return;
    }

    const int expert_id = expert_indices[token_idx * top_k + expert_slot];
    const float expert_weight = expert_weights[token_idx * top_k + expert_slot];

    if (expert_id < 0 || expert_id >= num_experts) {
        return;
    }

    __shared__ float shared_x[64];
    const int warp_id = threadIdx.x / 32;
    const int lane_id = threadIdx.x % 32;
    const int tokens_per_block = blockDim.x / hidden_size;

    const int local_token = threadIdx.x / hidden_size;
    const int local_hidden = threadIdx.x % hidden_size;

    if (local_token < tokens_per_block && token_idx + local_token < num_tokens) {
        shared_x[local_token * hidden_size + local_hidden] = x[(token_idx) * hidden_size + local_hidden];
    }
    __syncthreads();

    const float* expert_gate_proj = gate_proj + expert_id * intermediate_size * hidden_size;
    const float* expert_up_proj = up_proj + expert_id * intermediate_size * hidden_size;
    const float* expert_down_proj = down_proj + expert_id * hidden_size * intermediate_size;

    if (threadIdx.x < intermediate_size) {
        float gate_val = 0.0f;
        float up_val = 0.0f;


        #pragma unroll
        for (int i = 0; i < hidden_size; i += 4) {
            float x_val1 = shared_x[i];
            float x_val2 = shared_x[i + 1];
            float x_val3 = shared_x[i + 2];
            float x_val4 = shared_x[i + 3];

            gate_val += expert_gate_proj[threadIdx.x * hidden_size + i] * x_val1;
            gate_val += expert_gate_proj[threadIdx.x * hidden_size + i + 1] * x_val2;
            gate_val += expert_gate_proj[threadIdx.x * hidden_size + i + 2] * x_val3;
            gate_val += expert_gate_proj[threadIdx.x * hidden_size + i + 3] * x_val4;

            up_val += expert_up_proj[threadIdx.x * hidden_size + i] * x_val1;
            up_val += expert_up_proj[threadIdx.x * hidden_size + i + 1] * x_val2;
            up_val += expert_up_proj[threadIdx.x * hidden_size + i + 2] * x_val3;
            up_val += expert_up_proj[threadIdx.x * hidden_size + i + 3] * x_val4;
        }

        gate_val = SILU(gate_val);
        float intermediate_val = gate_val * up_val;


        float down_val = 0.0f;
        #pragma unroll
        for (int i = 0; i < intermediate_size; i += 8) {
            down_val += expert_down_proj[hidden_dim * intermediate_size + i + 0] * intermediate_val;
        }


        atomicAdd(&output[token_idx * hidden_size + hidden_dim], down_val * expert_weight);
    }
}
torch::Tensor moe_gated_gemm_forward(
    torch::Tensor x,
    torch::Tensor gate_proj,
    torch::Tensor up_proj,
    torch::Tensor down_proj,
    torch::Tensor expert_indices,
    torch::Tensor expert_weights
) {
    const at::cuda::OptionalCUDAGuard guard(device_of(x));

    const int num_tokens = x.size(0);
    const int hidden_size = x.size(1);
    const int num_experts = gate_proj.size(0);
    const int intermediate_size = gate_proj.size(1);
    const int top_k = expert_indices.size(1);

    auto output = torch::zeros({num_tokens, hidden_size}, torch::dtype(torch::kFloat32).device(x.device()));

    if (num_tokens == 0) {
        return output;
    }

    const int threads_per_block = 128;
    const int total_elements = num_tokens * top_k * hidden_size;
    const int num_blocks = CEILDIV(total_elements, threads_per_block);

    hipLaunchKernelGGL(
        moe_gated_gemm_kernel,
        dim3(num_blocks),
        dim3(threads_per_block),
        0, 0,
        x.data_ptr<float>(),
        gate_proj.data_ptr<float>(),
        up_proj.data_ptr<float>(),
        down_proj.data_ptr<float>(),
        expert_indices.data_ptr<int>(),
        expert_weights.data_ptr<float>(),
        output.data_ptr<float>(),
        num_tokens,
        num_experts,
        hidden_size,
        intermediate_size,
        top_k
    );

    return output;
}
"""

# Load the custom kernel
moe_gemm = load_inline(
    name="moe_gated_gemm",
    cpp_sources=cpp_source,
    functions=["moe_gated_gemm_forward"],
    verbose=True,
    is_python_module=True,
    with_cuda=True,
)

class ModelNew(nn.Module):
    def __init__(
        self,
        hidden_size: int,
        intermediate_size: int,
        num_experts: int,
    ):
        super().__init__()
        self.hidden_size = hidden_size
        self.intermediate_size = intermediate_size
        self.num_experts = num_experts

        self.gate_proj = nn.Parameter(
            torch.randn(num_experts, intermediate_size, hidden_size) * 0.02
        )
        self.up_proj = nn.Parameter(
            torch.randn(num_experts, intermediate_size, hidden_size) * 0.02
        )
        self.down_proj = nn.Parameter(
            torch.randn(num_experts, hidden_size, intermediate_size) * 0.02
        )

        self.moe_gemm_kernel = moe_gemm

    def forward(
        self,
        x: torch.Tensor,
        expert_indices: torch.Tensor,
        expert_weights: torch.Tensor,
    ) -> torch.Tensor:
        batch, seq_len, _ = x.shape

        x_flat = x.view(batch * seq_len, self.hidden_size)

        # Reshape indices and weights for kernel
        expert_indices_flat = expert_indices.view(batch * seq_len, -1)
        expert_weights_flat = expert_weights.view(batch * seq_len, -1)

        # Call fused kernel
        output_flat = self.moe_gemm_kernel.moe_gated_gemm_forward(
            x_flat,
            self.gate_proj,
            self.up_proj,
            self.down_proj,
            expert_indices_flat.int(),
            expert_weights_flat.float()
        )

        return output_flat.view(batch, seq_len, self.hidden_size)

# Configuration
batch_size = 4
seq_len = 2048
hidden_size = 4096
intermediate_size = 14336
num_experts = 8
top_k = 2

def get_inputs():
    x = torch.randn(batch_size, seq_len, hidden_size)

    expert_indices = torch.stack([
        torch.randperm(num_experts)[:top_k]
        for _ in range(batch_size * seq_len)
    ]).view(batch_size, seq_len, top_k)

    expert_weights = F.softmax(torch.randn(batch_size, seq_len, top_k), dim=-1)

    return [x, expert_indices, expert_weights]

def get_init_inputs():
    return [hidden_size, intermediate_size, num_experts]

import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Set HIP compiler
os.environ["CXX"] = "hipcc"

# Custom HIP kernel for fused FP8 matmul
fp8_matmul_hip_source = '''
#include <hip/hip_runtime.h>
#include <hip/hip_fp8.h>
#include <math.h>

#define BLOCK_SIZE_M 128
#define BLOCK_SIZE_N 128
#define BLOCK_SIZE_K 32
#define THREAD_M 16
#define THREAD_N 16

using fp8_type = __hip_fp8_e4m3;

__device__ __forceinline__ float compute_scale_kernel(const float* x, int size) {
    float local_max = 0.0f;
    for(int i = 0; i < size; i++) {
        float val = fabs(x[i]);
        local_max = fmaxf(local_max, val);
    }
    return local_max;
}

// Optimized FP8 matmul kernel for MI300X
// Fuses: scale computation + quantization + GEMM
extern "C" __global__ void fp8_matmul_fused_kernel(
    const float* input,          // Input: (M, K)
    const float* weight,         // Weight: (K, N) - already transposed
    float* output,               // Output: (M, N)
    const int M,
    const int K,
    const int N
) {
    // Shared memory for tiling
    __shared__ float s_input[BLOCK_SIZE_M][BLOCK_SIZE_K];
    __shared__ float s_weight[BLOCK_SIZE_K][BLOCK_SIZE_N];

    // Local registers for accumulation
    float accum[THREAD_M / 4][THREAD_N / 4];
    #pragma unroll
    for(int i = 0; i < THREAD_M / 4; i++) {
        #pragma unroll
        for(int j = 0; j < THREAD_N / 4; j++) {
            accum[i][j] = 0.0f;
        }
    }

    // Global thread indices
    const int thread_m = threadIdx.x / (BLOCK_SIZE_N / THREAD_N);
    const int thread_n = threadIdx.x % (BLOCK_SIZE_N / THREAD_N);
    const int batch_offset_m = blockIdx.x * BLOCK_SIZE_M;
    const int batch_offset_n = blockIdx.y * BLOCK_SIZE_N;

    // FP8 max values for E4M3
    const float fp8_max = 448.0f;

    // Iterate over K dimension in tiles
    for(int k = 0; k < K; k += BLOCK_SIZE_K) {
        // Load input tile with bounds checking
        #pragma unroll
        for(int i = 0; i < THREAD_M; i += 4) {
            int global_m = batch_offset_m + thread_m * THREAD_M + i;
            int global_k = k + threadIdx.x % (BLOCK_SIZE_K / 4);

            if(global_m < M && global_k < K) {
                s_input[thread_m * THREAD_M + i][global_k] = input[global_m * K + global_k];
            }
        }

        // Load weight tile with bounds checking (weight is already transposed: (K, N))
        #pragma unroll
        for(int j = 0; j < THREAD_N; j += 4) {
            int global_k = k + threadIdx.x / (BLOCK_SIZE_N / THREAD_N * 4);
            int global_n = batch_offset_n + thread_n * THREAD_N + j;

            if(global_k < K && global_n < N) {
                s_weight[global_k][global_n] = weight[global_k * N + global_n];
            }
        }

        __syncthreads();

        // Compute tile with FP8 quantization on-the-fly
        #pragma unroll
        for(int kk = 0; kk < BLOCK_SIZE_K; kk++) {
            // Load data from shared memory to registers
            float input_regs[THREAD_M / 4];
            float weight_regs[THREAD_N / 4];

            #pragma unroll
            for(int i = 0; i < THREAD_M / 4; i++) {
                int local_m = thread_m * THREAD_M + i * 4;
                input_regs[i] = s_input[local_m][kk];
            }

            #pragma unroll
            for(int j = 0; j < THREAD_N / 4; j++) {
                int local_n = thread_n * THREAD_N + j * 4;
                weight_regs[j] = s_weight[kk][local_n];
            }

            // Compute dot product with FP8 quantization
            #pragma unroll
            for(int i = 0; i < THREAD_M / 4; i++) {
                #pragma unroll
                for(int j = 0; j < THREAD_N / 4; j++) {
                    // Quantize inputs to FP8 on-the-fly
                    float in_val = input_regs[i];
                    float w_val = weight_regs[j];

                    // Simple quantization (clamp to FP8 range)
                    in_val = fminf(fmaxf(in_val, -fp8_max), fp8_max);
                    w_val = fminf(fmaxf(w_val, -fp8_max), fp8_max);

                    // Accumulate
                    accum[i][j] += in_val * w_val;
                }
            }
        }

        __syncthreads();
    }

    // Write results to output
    #pragma unroll
    for(int i = 0; i < THREAD_M / 4; i++) {
        int global_m = batch_offset_m + thread_m * THREAD_M + i * 4;
        if(global_m < M) {
            #pragma unroll
            for(int j = 0; j < THREAD_N / 4; j++) {
                int global_n = batch_offset_n + thread_n * THREAD_N + j * 4;
                if(global_n < N) {
                    output[global_m * N + global_n] = accum[i][j];
                }
            }
        }
    }
}

// Fused scale computation and quantization kernel
__global__ void compute_fp8_scales_kernel(
    const float* x,
    const float* w,
    float* x_scale,
    float* w_scale,
    int M,
    int K,
    int N
) {
    __shared__ float s_x_max[256];
    __shared__ float s_w_max[256];

    int tid = threadIdx.x;
    int idx = blockIdx.x * blockDim.x + tid;

    const float fp8_max = 448.0f;

    // Compute max for input tensor (per-tensor)
    float local_x_max = 0.0f;
    if(blockIdx.x == 0) {  // Only one block for per-tensor scale
        for(int i = tid; i < M * K; i += blockDim.x) {
            local_x_max = fmaxf(local_x_max, fabsf(x[i]));
        }
    }

    // Compute max for weight tensor (per-tensor)
    float local_w_max = 0.0f;
    if(blockIdx.x == 0) {  // Only one block for per-tensor scale
        for(int i = tid; i < K * N; i += blockDim.x) {
            local_w_max = fmaxf(local_w_max, fabsf(w[i]));
        }
    }

    s_x_max[tid] = local_x_max;
    s_w_max[tid] = local_w_max;
    __syncthreads();

    // Warp reduction
    #pragma unroll
    for(int offset = 128; offset > 0; offset >>= 1) {
        if(tid < offset) {
            s_x_max[tid] = fmaxf(s_x_max[tid], s_x_max[tid + offset]);
            s_w_max[tid] = fmaxf(s_w_max[tid], s_w_max[tid + offset]);
        }
    }
    __syncthreads();

    if(tid == 0) {
        x_scale[0] = fp8_max / fmaxf(s_x_max[0], 1e-12f);
        w_scale[0] = fp8_max / fmaxf(s_w_max[0], 1e-12f);
    }
}

// Wrapper functions to call from PyTorch
torch::Tensor fp8_matmul_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor weight_t
) {
    const int M = input.size(0);
    const int K = input.size(1);
    const int N = weight.size(1);

    auto output = torch::zeros({M, N}, input.options());

    // Compute scales
    auto x_scale = torch::zeros({1}, torch::dtype(torch::kFloat32).device(input.device()));
    auto w_scale = torch::zeros({1}, torch::dtype(torch::kFloat32).device(input.device()));

    const int threads = 256;
    const int blocks = 1;

    compute_fp8_scales_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        weight_t.data_ptr<float>(),
        x_scale.data_ptr<float>(),
        w_scale.data_ptr<float>(),
        M, K, N
    );

    // Launch fused kernel
    dim3 block_dim(256);
    dim3 grid_dim((M + BLOCK_SIZE_M - 1) / BLOCK_SIZE_M, 
                  (N + BLOCK_SIZE_N - 1) / BLOCK_SIZE_N);

    fp8_matmul_fused_kernel<<<grid_dim, block_dim>>>(
        input.data_ptr<float>(),
        weight_t.data_ptr<float>(),
        output.data_ptr<float>(),
        M, K, N
    );

    // Apply scaling to output
    output = output * (1.0f / (x_scale * w_scale).item<float>());

    return output;
}
'''

# Compile the custom kernel
fp8_matmul_hip = load_inline(
    name="fp8_matmul_hip",
    cpp_sources=fp8_matmul_hip_source,
    functions=["fp8_matmul_forward"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, M: int, K: int, N: int, use_e4m3: bool = True):
        super().__init__()
        self.M = M
        self.K = K
        self.N = N
        self.use_e4m3 = use_e4m3

        # Store weight pre-transposed for efficiency
        weight = torch.randn(K, N) * 0.02
        self.weight = nn.Parameter(weight)
        self.register_buffer('weight_t', weight.t().contiguous())

        # Bind custom kernel
        self.fp8_matmul = fp8_matmul_hip

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        input_dtype = x.dtype
        batch_size = x.shape[0]
        seq_len = x.shape[1]

        # Reshape for matmul
        x_2d = x.view(-1, self.K).contiguous()

        # Call custom fused kernel
        out = self.fp8_matmul.fp8_matmul_forward(x_2d, self.weight, self.weight_t)

        return out.view(batch_size, seq_len, self.N).to(input_dtype)

# Configuration
batch_size = 8
seq_len = 2048
M = batch_size * seq_len
K = 4096
N = 4096
use_e4m3 = True

def get_inputs():
    return [torch.randn(batch_size, seq_len, K, dtype=torch.float16).cuda()]

def get_init_inputs():
    return [M, K, N, use_e4m3]

import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# Fused GQA attention kernel with RoPE, implicit KV repetition, and causal mask
gqa_attention_cpp_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>
#include <math.h>

#define TILE_SIZE 64
#define WARP_SIZE 32

// Helper function to compute rotary embedding
__device__ __forceinline__ void apply_rope(float& x, float& y, float cos_val, float sin_val) {
    float x_new = x * cos_val - y * sin_val;
    float y_new = x * sin_val + y * cos_val;
    x = x_new;
    y = y_new;
}

__global__ void gqa_attention_kernel(
    const float* __restrict__ q,      // [batch, num_heads, seq_len, head_dim]
    const float* __restrict__ k,      // [batch, num_kv_heads, seq_len, head_dim]
    const float* __restrict__ v,      // [batch, num_kv_heads, seq_len, head_dim]
    float* __restrict__ out,          // [batch, num_heads, seq_len, head_dim]
    const float* __restrict__ cos,    // [1, 1, seq_len, head_dim]
    const float* __restrict__ sin,    // [1, 1, seq_len, head_dim]
    int batch_size,
    int num_heads,
    int num_kv_heads,
    int seq_len,
    int head_dim,
    float softmax_scale
) {
    // Block and thread indices
    int batch_idx = blockIdx.x;
    int head_idx = blockIdx.y;
    int kv_head_idx = head_idx / (num_heads / num_kv_heads);

    // Each thread block processes a tile of query positions
    int q_start = blockIdx.z * TILE_SIZE;
    int q_end = min(q_start + TILE_SIZE, seq_len);

    // Shared memory for Q tile (to reduce global memory access)
    __shared__ float shared_q[TILE_SIZE][64];

    // Shared memory for attention scores (partial)
    __shared__ float shared_scores[TILE_SIZE][TILE_SIZE];

    // Registers for current thread's query
    float q_vec[64];  // Max head_dim = 128, so 64 pairs

    int tid = threadIdx.x;
    int lane = tid % WARP_SIZE;
    int warp_id = tid / WARP_SIZE;

    // Process each query position in the tile
    for (int q_pos = q_start + warp_id; q_pos < q_end; q_pos += blockDim.x / WARP_SIZE) {
        // Load query vector and apply RoPE
        // Load 2 elements per thread (x, y pair for RoPE)
        for (int d = lane * 2; d < head_dim; d += WARP_SIZE * 2) {
            int q_idx = ((batch_idx * num_heads + head_idx) * seq_len + q_pos) * head_dim + d;
            float q_x = q[q_idx];
            float q_y = q[q_idx + 1];

            // Apply RoPE
            int cos_sin_idx = q_pos * head_dim + d;
            float cos_val = cos[cos_sin_idx];
            float sin_val = sin[cos_sin_idx];

            apply_rope(q_x, q_y, cos_val, sin_val);

            q_vec[d] = q_x;
            q_vec[d + 1] = q_y;
        }

        __syncthreads();

        // Compute attention scores for this query position
        // For causal attention, we only compute scores for keys <= q_pos
        for (int k_pos = lane; k_pos <= q_pos; k_pos += WARP_SIZE) {
            // Load key vector, apply RoPE, and compute dot product
            float score = 0.0f;

            for (int d = 0; d < head_dim; d += 2) {
                int k_idx = ((batch_idx * num_kv_heads + kv_head_idx) * seq_len + k_pos) * head_dim + d;
                float k_x = k[k_idx];
                float k_y = k[k_idx + 1];

                // Apply RoPE to key
                int cos_sin_idx = k_pos * head_dim + d;
                float cos_val = cos[cos_sin_idx];
                float sin_val = sin[cos_sin_idx];

                apply_rope(k_x, k_y, cos_val, sin_val);

                // Accumulate dot product
                score += q_vec[d] * k_x + q_vec[d + 1] * k_y;
            }

            // Apply softmax scaling
            score *= softmax_scale;

            // Store score (causal mask already applied by loop condition)
            if (q_pos < q_end && k_pos <= q_pos) {
                shared_scores[q_pos - q_start][k_pos] = score;
            }
        }
    }

    __syncthreads();

    // Compute softmax and accumulate values
    for (int q_pos = q_start + warp_id; q_pos < q_end; q_pos += blockDim.x / WARP_SIZE) {
        // Compute softmax for this query position
        float max_score = -INFINITY;

        // Find max for numerical stability
        for (int k_pos = lane; k_pos <= q_pos; k_pos += WARP_SIZE) {
            float score = shared_scores[q_pos - q_start][k_pos];
            if (score > max_score) max_score = score;
        }

        // Warp-level reduction for max
        for (int offset = WARP_SIZE / 2; offset > 0; offset /= 2) {
            float other_max = __shfl_xor(max_score, offset);
            if (other_max > max_score) max_score = other_max;
        }

        // Compute sum of exponentials
        float sum_exp = 0.0f;
        for (int k_pos = lane; k_pos <= q_pos; k_pos += WARP_SIZE) {
            float score = shared_scores[q_pos - q_start][k_pos];
            float exp_score = expf(score - max_score);
            sum_exp += exp_score;
            shared_scores[q_pos - q_start][k_pos] = exp_score;  // Store for later use
        }

        // Warp-level reduction for sum
        for (int offset = WARP_SIZE / 2; offset > 0; offset /= 2) {
            sum_exp += __shfl_xor(sum_exp, offset);
        }

        // Normalize and accumulate values
        float inv_sum_exp = 1.0f / sum_exp;

        // Accumulate weighted values
        for (int d = lane * 2; d < head_dim; d += WARP_SIZE * 2) {
            float out_x = 0.0f;
            float out_y = 0.0f;

            for (int k_pos = 0; k_pos <= q_pos; ++k_pos) {
                // Value from shared memory
                int v_idx = ((batch_idx * num_kv_heads + kv_head_idx) * seq_len + k_pos) * head_dim + d;
                float v_x = v[v_idx];
                float v_y = v[v_idx + 1];

                float weight = shared_scores[q_pos - q_start][k_pos] * inv_sum_exp;
                out_x += v_x * weight;
                out_y += v_y * weight;
            }

            // Store output
            int out_idx = ((batch_idx * num_heads + head_idx) * seq_len + q_pos) * head_dim + d;
            out[out_idx] = out_x;
            out[out_idx + 1] = out_y;
        }
    }
}

torch::Tensor gqa_attention_hip(
    torch::Tensor q, torch::Tensor k, torch::Tensor v,
    torch::Tensor cos, torch::Tensor sin,
    int num_kv_heads, float softmax_scale
) {
    auto batch_size = q.size(0);
    auto num_heads = q.size(1);
    auto seq_len = q.size(2);
    auto head_dim = q.size(3);

    auto out = torch::zeros_like(q);

    dim3 grid(batch_size, num_heads, (seq_len + TILE_SIZE - 1) / TILE_SIZE);
    dim3 block(256);  // 8 warps per block

    hipLaunchKernelGGL(
        gqa_attention_kernel,
        grid,
        block,
        0,
        at::hip::getCurrentHIPStreamMasqueradingAsCUDA(),
        q.data_ptr<float>(),
        k.data_ptr<float>(),
        v.data_ptr<float>(),
        out.data_ptr<float>(),
        cos.data_ptr<float>(),
        sin.data_ptr<float>(),
        batch_size,
        num_heads,
        num_kv_heads,
        seq_len,
        head_dim,
        softmax_scale
    );

    return out;
}
"""

gqa_attention = load_inline(
    name="gqa_attention",
    cpp_sources=gqa_attention_cpp_source,
    functions=["gqa_attention_hip"],
    verbose=True,
)

class RotaryEmbedding(nn.Module):
    def __init__(self, dim, max_position_embeddings=4096, base=10000.0):
        super().__init__()
        self.dim = dim
        self.max_position_embeddings = max_position_embeddings
        self.base = base
        inv_freq = 1.0 / (self.base ** (torch.arange(0, self.dim, 2, dtype=torch.float32) / self.dim))
        self.register_buffer("inv_freq", inv_freq, persistent=False)

    @torch.no_grad()
    def forward(self, x, seq_len=None):
        if seq_len is None:
            seq_len = x.shape[-2]
        t = torch.arange(seq_len, device=x.device, dtype=torch.float32)
        freqs = torch.outer(t, self.inv_freq)
        emb = torch.cat((freqs, freqs), dim=-1)
        return emb.cos().unsqueeze(0).unsqueeze(0), emb.sin().unsqueeze(0).unsqueeze(0)

class ModelNew(nn.Module):
    def __init__(
        self,
        hidden_size: int,
        num_attention_heads: int,
        num_key_value_heads: int,
        head_dim: int,
        max_position_embeddings: int = 4096,
        rope_theta: float = 10000.0,
        attention_dropout: float = 0.0,
    ):
        super().__init__()
        self.hidden_size = hidden_size
        self.num_heads = num_attention_heads
        self.num_kv_heads = num_key_value_heads
        self.head_dim = head_dim
        self.num_key_value_groups = num_attention_heads // num_key_value_heads
        self.attention_dropout = attention_dropout
        self.softmax_scale = head_dim ** (-0.5)

        # Separate projections for Q, K, V
        self.q_proj = nn.Linear(hidden_size, num_attention_heads * head_dim, bias=False)
        self.k_proj = nn.Linear(hidden_size, num_key_value_heads * head_dim, bias=False)
        self.v_proj = nn.Linear(hidden_size, num_key_value_heads * head_dim, bias=False)
        self.o_proj = nn.Linear(num_attention_heads * head_dim, hidden_size, bias=False)

        # Rotary embeddings
        self.rotary_emb = RotaryEmbedding(
            head_dim,
            max_position_embeddings=max_position_embeddings,
            base=rope_theta,
        )

        # Fused GQA attention kernel
        self.gqa_attention = gqa_attention

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        bsz, q_len, _ = hidden_states.size()

        # Project Q, K, V
        query_states = self.q_proj(hidden_states)
        key_states = self.k_proj(hidden_states)
        value_states = self.v_proj(hidden_states)

        # Reshape for multi-head attention
        query_states = query_states.view(bsz, q_len, self.num_heads, self.head_dim).transpose(1, 2)
        key_states = key_states.view(bsz, q_len, self.num_kv_heads, self.head_dim).transpose(1, 2)
        value_states = value_states.view(bsz, q_len, self.num_kv_heads, self.head_dim).transpose(1, 2)

        # Get rotary embeddings
        cos, sin = self.rotary_emb(value_states, seq_len=q_len)

        # Fused GQA attention with implicit KV repetition (no explicit expand!)
        attn_output = self.gqa_attention.gqa_attention_hip(
            query_states, key_states, value_states,
            cos, sin, self.num_kv_heads, self.softmax_scale
        )

        # Reshape output
        attn_output = attn_output.transpose(1, 2).contiguous()
        attn_output = attn_output.reshape(bsz, q_len, self.num_heads * self.head_dim)

        # Output projection
        attn_output = self.o_proj(attn_output)

        return attn_output

# Llama 3 70B style configuration
