import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import math
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# Define the C++ and CUDA sources
cpp_source = """
torch::Tensor moe_gated_gemm_forward(
    torch::Tensor x,
    torch::Tensor gate_proj,
    torch::Tensor up_proj,
    torch::Tensor down_proj,
    torch::Tensor expert_indices,
    torch::Tensor expert_weights
);
"""

hip_source = R"(
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <c10/cuda/CUDAGuard.h>

#define CEILDIV(a, b) ((a + b - 1) / b)

#define SILU(x) ((x) / (1.0f + expf(-(x))))

__global__ void moe_gated_gemm_kernel(
    const float* __restrict__ x,
    const float* __restrict__ gate_proj,
    const float* __restrict__ up_proj,
    const float* __restrict__ down_proj,
    const int* __restrict__ expert_indices,
    const float* __restrict__ expert_weights,
    float* __restrict__ output,
    const int num_tokens,
    const int num_experts,
    const int hidden_size,
    const int intermediate_size,
    const int top_k
) {
    const int tid = blockIdx.x * blockDim.x + threadIdx.x;

    if (tid >= num_tokens * top_k * hidden_size) {
        return;
    }

    const int token_idx = tid / (top_k * hidden_size);
    const int expert_slot = (tid / hidden_size) % top_k;
    const int hidden_dim = tid % hidden_size;

    if (token_idx >= num_tokens) {
        return;
    }

    const int expert_id = expert_indices[token_idx * top_k + expert_slot];
    const float expert_weight = expert_weights[token_idx * top_k + expert_slot];

    if (expert_id < 0 || expert_id >= num_experts || expert_weight == 0.0f) {
        return;
    }

    // Load x once for this token
    float* token_x = (float*)malloc(hidden_size * sizeof(float));
    for (int i = 0; i < hidden_size; i++) {
        token_x[i] = x[token_idx * hidden_size + i];
    }

    // Compute gate and up projections
    const float* expert_gate_proj = gate_proj + expert_id * intermediate_size * hidden_size;
    const float* expert_up_proj = up_proj + expert_id * intermediate_size * hidden_size;
    const float* expert_down_proj = down_proj + expert_id * hidden_size * intermediate_size;

    float intermediate_sum = 0.0f;

    for (int inter_idx = threadIdx.x; inter_idx < intermediate_size; inter_idx += blockDim.x) {
        float gate_val = 0.0f;
        float up_val = 0.0f;

        for (int i = 0; i < hidden_size; i++) {
            float x_val = token_x[i];
            gate_val += expert_gate_proj[inter_idx * hidden_size + i] * x_val;
            up_val += expert_up_proj[inter_idx * hidden_size + i] * x_val;
        }

        float silu_gate = SILU(gate_val);
        intermediate_sum += silu_gate * up_val;
    }

    __syncthreads();

    // Now do the down projection: convert from intermediate_size back to hidden_size
    if (hidden_dim < hidden_size) {
        float down_val = 0.0f;

        for (int i = 0; i < intermediate_size; i++) {
            float intermediate_val;
            if (i == threadIdx.x) {
                intermediate_val = intermediate_sum;
            } else {
                intermediate_val = 0.0f;
            }
            down_val += expert_down_proj[hidden_dim * intermediate_size + i] * intermediate_val;
        }

        // Accumulate weighted result using atomic operations
        atomicAdd(&output[token_idx * hidden_size + hidden_dim], down_val * expert_weight);
    }

    free(token_x);
}

torch::Tensor moe_gated_gemm_forward(
    torch::Tensor x,
    torch::Tensor gate_proj,
    torch::Tensor up_proj,
    torch::Tensor down_proj,
    torch::Tensor expert_indices,
    torch::Tensor expert_weights
) {
    auto device = x.device();
    const at::cuda::OptionalCUDAGuard device_guard(device);

    const int num_tokens = x.size(0);
    const int hidden_size = x.size(1);
    const int num_experts = gate_proj.size(0);
    const int intermediate_size = gate_proj.size(1);
    const int top_k = expert_indices.size(1);

    auto output = torch::zeros({num_tokens, hidden_size}, torch::dtype(torch::kFloat32).device(device));

    if (num_tokens == 0 || top_k == 0) {
        return output;
    }

    const int threads_per_block = 128;
    const int total_elements = num_tokens * top_k * hidden_size;
    const int num_blocks = CEILDIV(total_elements, threads_per_block);

    hipLaunchKernelGGL(
        moe_gated_gemm_kernel,
        dim3(num_blocks),
        dim3(threads_per_block),
        0, 0,
        x.data_ptr<float>(),
        gate_proj.data_ptr<float>(),
        up_proj.data_ptr<float>(),
        down_proj.data_ptr<float>(),
        expert_indices.data_ptr<int>(),
        expert_weights.data_ptr<float>(),
        output.data_ptr<float>(),
        num_tokens,
        num_experts,
        hidden_size,
        intermediate_size,
        top_k
    );

    return output;
}
)"

moe_gemm = load_inline(
    name="moe_gated_gemm",
    cpp_sources=cpp_source,
    functions=["moe_gated_gemm_forward"],
    verbose=True,
    is_python_module=True,
    with_cuda=True,
)

class ModelNew(nn.Module):
    def __init__(
        self,
        hidden_size: int,
        intermediate_size: int,
        num_experts: int,
    ):
        super().__init__()
        self.hidden_size = hidden_size
        self.intermediate_size = intermediate_size
        self.num_experts = num_experts

        self.gate_proj = nn.Parameter(
            torch.randn(num_experts, intermediate_size, hidden_size) * 0.02
        )
        self.up_proj = nn.Parameter(
            torch.randn(num_experts, intermediate_size, hidden_size) * 0.02
        )
        self.down_proj = nn.Parameter(
            torch.randn(num_experts, hidden_size, intermediate_size) * 0.02
        )

        self.moe_gemm_kernel = moe_gemm

    def forward(
        self,
        x: torch.Tensor,
        expert_indices: torch.Tensor,
        expert_weights: torch.Tensor,
    ) -> torch.Tensor:
        batch, seq_len, _ = x.shape

        x_flat = x.view(batch * seq_len, self.hidden_size)

        expert_indices_flat = expert_indices.view(batch * seq_len, -1)
        expert_weights_flat = expert_weights.view(batch * seq_len, -1)

        output_flat = self.moe_gemm_kernel.moe_gated_gemm_forward(
            x_flat,
            self.gate_proj,
            self.up_proj,
            self.down_proj,
            expert_indices_flat.to(torch.int32),
            expert_weights_flat
        )

