            torch.randint(0, 256, (N, K // 2), dtype=torch.uint8)
        )

        self.register_buffer(
            "scales",
            torch.randn(N, self.num_groups, dtype=torch.float16).abs() * 0.1
        )

        # Store the custom kernel
        self.fused_gemm = int4_gemm_fused

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        batch_size, seq_len, _ = x.shape

        # Ensure input is in FP16
        x_fp16 = x.half()

        # Use the fused kernel - this combines unpacking, dequantization, and GEMM
        out = self.fused_gemm.int4_gemm_forward(
            x_fp16.view(batch_size, seq_len, self.K),  # Keep original shape
            self.weight_packed,
            self.scales,
            self.K,
            self.N,
            self.group_size
        )

        return out

