# Fused MoE HIP kernel - optimized version with better memory access
moe_hip_code = """
#include <hip/hip_runtime.h>
#include <math.h>

#define BLOCK_SIZE 256
#define ELEMS_PER_THREAD 16

extern "C" __global__ void fused_moe_kernel_optimized(
    const float* __restrict__ hidden_states,
    const float* __restrict__ gate_proj,
    const float* __restrict__ up_proj,
    const float* __restrict__ down_proj,
    const int* __restrict__ topk_idx,
    const float* __restrict__ topk_weight,
    float* __restrict__ output,
    int num_tokens,
    int hidden_size,
    int intermediate_size,
    int top_k
) {
    int token_id = blockIdx.x;
    if (token_id >= num_tokens) return;

    int tid = threadIdx.x;
    int block_dim = blockDim.x;

    // Shared memory for token vector and intermediate results
    extern __shared__ float shared_mem[];
    float* shared_token = shared_mem;
    float* shared_gate = &shared_mem[hidden_size];
    float* shared_up = &shared_mem[hidden_size + intermediate_size];

    // Load token into shared memory (coalesced access)
    for (int i = tid; i < hidden_size; i += block_dim) {
        shared_token[i] = hidden_states[token_id * hidden_size + i];
    }
    __syncthreads();

    // Each thread computes multiple output elements
    float output_local[ELEMS_PER_THREAD];
    for (int i = 0; i < ELEMS_PER_THREAD; i++) {
        output_local[i] = 0.0f;
    }

    // Compute output start index for this thread
    int j_start = tid * ELEMS_PER_THREAD;
    int j_end = min(j_start + ELEMS_PER_THREAD, hidden_size);

    // Process each expert
    for (int k = 0; k < top_k; k++) {
        int expert_id = topk_idx[token_id * top_k + k];
        float weight = topk_weight[token_id * top_k + k];

        if (expert_id < 0 || weight == 0.0f) continue;

        // Compute gate_proj * token and up_proj * token for all intermediate dimensions
        // These can be shared across all output elements
        int expert_offset = expert_id * intermediate_size * hidden_size;
        for (int i = tid; i < intermediate_size; i += block_dim) {
            float sum_gate = 0.0f;
            float sum_up = 0.0f;
            int row_offset = expert_offset + i * hidden_size;

            // Dot product between token and weight row
            #pragma unroll
            for (int h = 0; h < hidden_size; h++) {
                float val = shared_token[h];
                sum_gate += gate_proj[row_offset + h] * val;
                sum_up += up_proj[row_offset + h] * val;
            }

            // SiLU activation
            float gate_silu = sum_gate / (1.0f + __expf(-sum_gate));
            shared_gate[i] = gate_silu * sum_up;
        }
        __syncthreads();

        // Now compute down projection: sum_i down_proj[j][i] * shared_gate[i]
        expert_offset = expert_id * hidden_size * intermediate_size;
        for (int j = j_start; j < j_end; j++) {
            float sum = 0.0f;
            int row_offset = expert_offset + j * intermediate_size;

            #pragma unroll 8
            for (int i = 0; i < intermediate_size; i++) {
                sum += down_proj[row_offset + i] * shared_gate[i];
            }

            output_local[j - j_start] += weight * sum;
        }
        __syncthreads();
    }

    // Write output (coalesced writes)
    for (int j = j_start; j < j_end; j++) {
        output[token_id * hidden_size + j] = output_local[j - j_start];
    }
}

torch::Tensor fused_moe_hip(
    torch::Tensor hidden_states,
    torch::Tensor gate_proj,
    torch::Tensor up_proj,
    torch::Tensor down_proj,
    torch::Tensor topk_idx,
    torch::Tensor topk_weight
) {
    auto num_tokens = hidden_states.size(0);
    auto hidden_size = hidden_states.size(1);
    auto intermediate_size = gate_proj.size(1);
    auto top_k = topk_idx.size(1);

    auto output = torch::zeros_like(hidden_states);

    const int block_size = BLOCK_SIZE;
    const int num_blocks = num_tokens;

    // Shared memory: token + intermediate buffers
    size_t shared_mem_size = (hidden_size + intermediate_size * 2) * sizeof(float);

    fused_moe_kernel_optimized<<<num_blocks, block_size, shared_mem_size>>>(
        hidden_states.data_ptr<float>(),
        gate_proj.data_ptr<float>(),
        up_proj.data_ptr<float>(),
        down_proj.data_ptr<float>(),
        topk_idx.data_ptr<int>(),
        topk_weight.data_ptr<float>(),
        output.data_ptr<float>(),
        num_tokens,
        hidden_size,
        intermediate_size,
        top_k
    );

    return output;
}
"""

# Compile the kernel
