hip_code = """
#include <torch/extension.h>
#include <hip/hip_runtime.h>

#define CEILDIV(a, b) ((a + b - 1) / b)

__global__ void moe_kernel(
    const float* __restrict__ x,
    const float* __restrict__ gate_proj,
    const float* __restrict__ up_proj,
    const float* __restrict__ down_proj,
    const int* __restrict__ expert_indices,
    const float* __restrict__ expert_weights,
    float* __restrict__ output,
    const int num_tokens,
    const int hidden_size,
    const int intermediate_size,
    const int top_k
) {
    const int token_idx = blockIdx.x;
    if (token_idx >= num_tokens) return;

    const int hidden_dim = threadIdx.x;
    if (hidden_dim >= hidden_size) return;

    for (int expert_slot = 0; expert_slot < top_k; expert_slot++) {
        const int expert_id = expert_indices[token_idx * top_k + expert_slot];
        const float expert_weight = expert_weights[token_idx * top_k + expert_slot];

        if (expert_id < 0 || expert_id >= gridDim.y) continue;

        const float* expert_gate = gate_proj + expert_id * intermediate_size * hidden_size;
        const float* expert_up = up_proj + expert_id * intermediate_size * hidden_size;
        const float* expert_down = down_proj + expert_id * hidden_size * intermediate_size;

        // Load token input
        const float* token_x = x + token_idx * hidden_size;

        // Compute intermediate projection using shared memory for caching
        __shared__ float inter_cache[128];

        float inter_sum = 0.0f;

        for (int i = threadIdx.x; i < intermediate_size; i += blockDim.x) {
            float gate_val = 0.0f;
            float up_val = 0.0f;

            // Accumulate gate and up projections
            for (int j = 0; j < hidden_size; j++) {
                float x_val = token_x[j];
                gate_val += expert_gate[i * hidden_size + j] * x_val;
                up_val += expert_up[i * hidden_size + j] * x_val;
            }

            // Apply SiLU activation and multiply
            float silu_gate = gate_val / (1.0f + expf(-gate_val));
            inter_sum += silu_gate * up_val;
        }

        inter_cache[threadIdx.x] = inter_sum;
        __syncthreads();

        // Down projection
        float down_val = 0.0f;
        for (int i = 0; i < intermediate_size; i++) {
            down_val += expert_down[hidden_dim * intermediate_size + i] * inter_cache[i];
        }

        // Atomic add weighted contribution
        atomicAdd(&output[token_idx * hidden_size + hidden_dim], down_val * expert_weight);
    }
}

torch::Tensor moe_gated_gemm_forward(
    torch::Tensor x,
    torch::Tensor gate_proj,
    torch::Tensor up_proj,
    torch::Tensor down_proj,
    torch::Tensor expert_indices,
    torch::Tensor expert_weights
) {
    auto device = x.device();
    const int num_tokens = x.size(0);
    const int hidden_size = x.size(1);
    const int num_experts = gate_proj.size(0);
    const int intermediate_size = gate_proj.size(1);
    const int top_k = expert_indices.size(1);

    auto output = torch::zeros({num_tokens, hidden_size}, torch::dtype(torch::kFloat32).device(device));

    const int num_blocks = num_tokens;
    const int threads_per_block = hidden_size;

    hipLaunchKernelGGL(
        moe_kernel,
        dim3(num_blocks),
        dim3(threads_per_block),
        0, 0,
        x.data_ptr<float>(),
        gate_proj.data_ptr<float>(),
        up_proj.data_ptr<float>(),
        down_proj.data_ptr<float>(),
        expert_indices.data_ptr<int>(),
        expert_weights.data_ptr<float>(),
        output.data_ptr<float>(),
        num_tokens,
        hidden_size,
        intermediate_size,
        top_k
    );

    C10_CUDA_KERNEL_LAUNCH_CHECK();

    return output;
}
"""

