# Simplified, debugged version of the HIP kernel
kimi_delta_attention_cpp_source = """
#include <hip/hip_runtime.h>
#include <ATen/ATen.h>

#define WARP_SIZE 32

__global__ void kimi_delta_attention_kernel(
    const float* __restrict__ q,
    const float* __restrict__ k,
    const float* __restrict__ v,
    const float* __restrict__ a,
    const float* __restrict__ beta,
    float* __restrict__ out,
    int batch_size,
    int seq_len,
    int num_heads,
    int head_dim_qk,
    int head_dim_v
) {
    // Grid: (batch_size, num_heads, head_dim_v)
    int batch_idx = blockIdx.x;
    int head_idx = blockIdx.y;
    int row = blockIdx.z;  // Row index in S matrix (0 to head_dim_v-1)

    int tid = threadIdx.x;
    int lane_id = tid % WARP_SIZE;

    // Calculate base offsets for this batch and head
    int batch_head_offset = (batch_idx * num_heads + head_idx);
    int qk_stride = seq_len * head_dim_qk;
    int v_stride = seq_len * head_dim_v;

    // Shared memory for one row of S matrix (size: head_dim_qk)
    extern __shared__ float shared_mem[];
    float* S_row = shared_mem;

    // Initialize S_row to zero
    for (int i = tid; i < head_dim_qk; i += blockDim.x) {
        S_row[i] = 0.0f;
    }
    __syncthreads();

    // Process all timesteps in sequence
    for (int t = 0; t < seq_len; ++t) {
        // Load k_t and q_t for this timestep (coalesced access)
        float k_val = (lane_id < head_dim_qk) ? k[batch_head_offset * qk_stride + t * head_dim_qk + lane_id] : 0.0f;
        float q_val = (lane_id < head_dim_qk) ? q[batch_head_offset * qk_stride + t * head_dim_qk + lane_id] : 0.0f;

        // Load v_t[row], a_t[row], beta_t (broadcast from first thread to avoid bank conflicts)
        // These are common for all lanes in the warp for this batch, head, row, and timestep
        float v_val = 0.0f, a_val = 0.0f, beta_val = 0.0f;
        if (tid == 0) {
            v_val = v[batch_head_offset * v_stride + t * head_dim_v + row];
            a_val = a[batch_head_offset * v_stride + t * head_dim_v + row];
            beta_val = beta[batch_idx * seq_len * num_heads + t * num_heads + head_idx];
        }

        // Broadcast values across the warp using 64-bit mask
        v_val = __shfl_sync(0xffffffffUL, v_val, 0);
        a_val = __shfl_sync(0xffffffffUL, a_val, 0);
        beta_val = __shfl_sync(0xffffffffUL, beta_val, 0);

        // Compute S_row @ k: dot product of S_row and k_t
        float sum = 0.0f;
        if (lane_id < head_dim_qk) {
            sum = S_row[lane_id] * k_val;
        }

        // Warp reduction with 64-bit mask
        for (int offset = WARP_SIZE / 2; offset > 0; offset /= 2) {
            sum += __shfl_down_sync(0xffffffffUL, sum, offset);
        }
        float S_k = sum;  // Only valid in lane 0
        S_k = __shfl_sync(0xffffffffUL, S_k, 0);  // Broadcast to all threads

        // Error = S_k - v_val
        float error = S_k - v_val;

        // Apply diagonal gating and update S
        if (lane_id < head_dim_qk) {
            // Diagonal gate: scale each element of S_row by a_val
            S_row[lane_id] *= a_val;
            // Delta rule: subtract beta * error * k_t^T
            S_row[lane_id] -= beta_val * error * k_val;
        }

        // Compute output: o[row] = (S @ q_t)[row]
        float out_val = (lane_id < head_dim_qk) ? S_row[lane_id] * q_val : 0.0f;
        for (int offset = WARP_SIZE / 2; offset > 0; offset /= 2) {
            out_val += __shfl_down_sync(0xffffffffUL, out_val, offset);
        }

        // Store output (only lane 0 writes)
        if (lane_id == 0) {
            out[batch_head_offset * v_stride + t * head_dim_v + row] = out_val;
        }

        __syncthreads();  // Ensure S_row is updated for next timestep
    }
}

torch::Tensor kimi_delta_attention_hip(
    torch::Tensor q,
    torch::Tensor k,
    torch::Tensor v,
    torch::Tensor a,
    torch::Tensor beta
) {
    // Input shape checks
    TORCH_CHECK(q.dim() == 4, "q must be 4D tensor (batch, seq, heads, dim_qk)");
    TORCH_CHECK(k.dim() == 4, "k must be 4D tensor (batch, seq, heads, dim_qk)");
    TORCH_CHECK(v.dim() == 4, "v must be 4D tensor (batch, seq, heads, dim_v)");
    TORCH_CHECK(a.dim() == 4, "a must be 4D tensor (batch, seq, heads, dim_v)");
    TORCH_CHECK(beta.dim() == 3, "beta must be 3D tensor (batch, seq, heads)");

    int batch_size = q.size(0);
    int seq_len = q.size(1);
    int num_heads = q.size(2);
    int head_dim_qk = q.size(3);
    int head_dim_v = v.size(3);

    // Output shape: (batch, seq, num_heads, head_dim_v)
    auto out = torch::zeros_like(v);

    // Ensure contiguous memory layout
    q = q.contiguous();
    k = k.contiguous();
    v = v.contiguous();
    a = a.contiguous();
    beta = beta.contiguous();

    // Grid: (batch_size, num_heads, head_dim_v)
    dim3 grid(batch_size, num_heads, head_dim_v);

    // Block: 128 threads (4 warps)
    dim3 block(128);

    // Shared memory: head_dim_qk floats per block
    size_t shared_mem_size = head_dim_qk * sizeof(float);

    // Launch kernel with default stream
    hipLaunchKernelGGL(
        kimi_delta_attention_kernel,
        grid,
        block,
        shared_mem_size,
        0,  // default stream
        q.data_ptr<float>(),
        k.data_ptr<float>(),
        v.data_ptr<float>(),
        a.data_ptr<float>(),
        beta.data_ptr<float>(),
        out.data_ptr<float>(),
        batch_size,
        seq_len,
        num_heads,
        head_dim_qk,
        head_dim_v
    );

    return out;
}
"""

